//! Envoy drives in the world (envoy-core-v2.md 3.1): the owner's own `envoy_drives` models (generated by
//! `pc/scripts/examples/envoy_drives/tools/make_drives.py`, original geometry and colour ramps, no game data) drawn
//! in the match, and the stand-in effects (rings, discs, spikes, bolts, beams) a fire leaves.
//!
//! Presentation only, read-only on the sim: a UI mod queues instances through `gd_ui_world_model(_ex)` /
//! `gd_ui_world_fx` during its present (melee_modhost::ui); [`commit`] publishes the present's list. The presenter
//! draws it with the effects layer (melee_gx::fx, docs/rust-port/notes/envoy-fx.md: [`world_frame`]) after the GX
//! frame, with the fight camera the fighter draw pass recorded ([`record_camera`], hooked as
//! `ftdrawcommon::WORLD_DRAW`: it copies the camera into a static and issues no GX and allocates nothing, so the
//! game-scope FIFO never carries a drive).
//! [`sprite_sheet`] rasterizes a model on the CPU (turning, `SPRITE_FRAMES` yaw steps) for the 2D cards.
//!
//! The meshes are decoded once (GXMS v2: positions, UVs, normals), normalised to a unit diameter, and coloured per
//! vertex from the shared atlas (base + glow rows); no textures reach the GPU.

use std::sync::{Mutex, OnceLock};

macro_rules! model {
    ($n:literal) => {
        include_bytes!(concat!("../../../../pc/scripts/examples/envoy_drives/models/", $n, ".gxmesh"))
    };
}

/// Model ids (gd_ui_world_model / gd_ui_model_tex): 0-5 the six legacy family bodies, 6 the glass shell, 7-9 the
/// legacy ring overlays; from [`PARTY_FIRST`] the Party pack set in `models/drive_party.txt` order (make_drives.py
/// writes both): 10 the Rare tier ring, 11 the Epic ring with its spark, 12 the ascended halo and star, then one model
/// per drive (46) and per Unique (16). The Party set shares one frame (no recentring: the tier ring under the form
/// and the halo over it line up with any body drawn at the same place, yaw and scale) and the 128 x 256 Party atlas.
pub const M_GLASS: usize = 6;
pub const PARTY_FIRST: usize = 10;
pub const M_RING_RARE: usize = 10;
pub const M_RING_EPIC: usize = 11;
pub const M_ASCENDED: usize = 12;
pub const PARTY_COUNT: usize = 65;
/// One past the Party set: where the Envoy model set starts.
pub const PARTY_END: usize = PARTY_FIRST + PARTY_COUNT;
/// The Envoy model set (docs/rust-port/notes/envoy-models1.md: items, map nodes, hearts, pool frames, keyword glyphs,
/// tag emblems, HUD bits, projectile bodies, map furniture, world pieces), generated by
/// `pc/scripts/examples/envoy_models/tools/make_models1.py`. Model id = [`EM_FIRST`] + the key's line in
/// `models/envoy_models.txt` ([`EM_KEYS`]); the generator writes the include list in the same order. They share the
/// Party frame (no recentring: a pool frame and its item line up at one place, yaw and scale) and have their own
/// atlas pair.
pub const EM_FIRST: usize = PARTY_END;
const EM_FILES: &[&[u8]] = &include!("../../../../pc/scripts/examples/envoy_models/models/envoy_models.inc.rs");
pub const EM_COUNT: usize = EM_FILES.len();
pub static EM_KEYS: &str = include_str!("../../../../pc/scripts/examples/envoy_models/models/envoy_models.txt");
pub const MODEL_COUNT: usize = EM_FIRST + EM_COUNT;
// a model id travels as a u16 (Inst::Model, melee_gx::fx::WorldDraw)
const _: () = assert!(MODEL_COUNT <= 65536);
/// The model id of Envoy model `key` (`"spark_ring"`, `"node_boss"`, `"frame_devil"`...), None if there is none.
pub fn em_model(key: &str) -> Option<usize> {
    EM_KEYS.lines().position(|k| k == key).map(|n| EM_FIRST + n)
}
/// The Party manifest (one key per line, model id = PARTY_FIRST + line): what UI mods look a drive's model up by.
pub static PARTY_KEYS: &str = include_str!("../../../../pc/scripts/examples/envoy_drives/models/drive_party.txt");
/// The ink outline is `melee_gx::fx::MAT_OUTLINE` (colour `melee_gx::fx::INK_RGB`): drive BODIES only (not tier
/// rings, the ascended overlay or the glass); the host drops the flag on any other model.
/// Whether a model is a drive body the outline pass should edge (legacy family bodies and every Party drive/Unique).
/// The Envoy model set may take the edge too (melee_gx::fx's ink pass pushes the hull behind its own body and widens
/// it for a model drawn large): the caller decides per draw.
pub fn is_drive_body(model: usize) -> bool {
    model < M_GLASS || (PARTY_FIRST + 3..MODEL_COUNT).contains(&model)
}
/// Uniques take a second, white edge outside the ink (DRIVE-MODELS.md 6: ink 0.09, white 0.16).
pub fn is_unique(model: usize) -> bool {
    (PARTY_END - 16..PARTY_END).contains(&model)
}
