/// The Party set's fixed frame: the parts box (-1..1) times HALF 2.2, so 4.4 world units is one model diameter.
const PARTY_SPAN: f32 = 4.4;

/// One decoded model: triangles (3 vertices each) in unit-diameter space, normals, base and glow colours.
pub struct Baked {
    pub pos: Vec<[f32; 3]>,
    pub nrm: Vec<[f32; 3]>,
    pub base: Vec<[f32; 3]>,
    pub glow: Vec<[f32; 3]>,
}

fn be32(d: &[u8], o: usize) -> u32 {
    u32::from_be_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
}
fn bef(d: &[u8], o: usize) -> f32 {
    f32::from_bits(be32(d, o))
}

/// A GXTX v1 RGBA8 image (4x4 tiles: 16 AR pairs, then 16 GB pairs) as (w, h, rgba rows).
pub fn decode_gxtx(d: &[u8]) -> Option<(usize, usize, Vec<u8>)> {
    if d.len() < 64 || &d[..4] != b"GXTX" || be32(d, 8) != 6 {
        return None;
    }
    let (w, h) = (be32(d, 12) as usize, be32(d, 16) as usize);
    let off = be32(d, 36) as usize;
    if w % 4 != 0 || h % 4 != 0 || d.len() < off + w * h * 4 {
        return None;
    }
    let mut out = vec![0u8; w * h * 4];
    let mut p = off;
    for ty in (0..h).step_by(4) {
        for tx in (0..w).step_by(4) {
            for i in 0..16 {
                let (x, y) = (tx + i % 4, ty + i / 4);
                let o = (y * w + x) * 4;
                out[o + 3] = d[p + i * 2];
                out[o] = d[p + i * 2 + 1];
                out[o + 1] = d[p + 32 + i * 2];
                out[o + 2] = d[p + 32 + i * 2 + 1];
            }
            p += 64;
        }
    }
    Some((w, h, out))
}

fn sample(img: &(usize, usize, Vec<u8>), u: f32, v: f32) -> [f32; 3] {
    let (w, h, px) = img;
    let x = ((u * *w as f32) as usize).min(w - 1);
    let y = ((v * *h as f32) as usize).min(h - 1);
    let o = (y * w + x) * 4;
    [px[o] as f32 / 255.0, px[o + 1] as f32 / 255.0, px[o + 2] as f32 / 255.0]
}

/// A GXMS v2 mesh, unrolled to triangles and normalised to a unit diameter around its centre.
pub fn decode_mesh(d: &[u8], atlas: &(usize, usize, Vec<u8>), glow: &(usize, usize, Vec<u8>)) -> Option<Baked> {
    decode_mesh_in(d, atlas, glow, None)
}

/// As [`decode_mesh`]; `fixed`: no recentring, divide by this span (the Party set's shared frame).
pub fn decode_mesh_in(d: &[u8], atlas: &(usize, usize, Vec<u8>), glow: &(usize, usize, Vec<u8>), fixed: Option<f32>) -> Option<Baked> {
    if d.len() < 36 || &d[..4] != b"GXMS" || be32(d, 4) != 2 {
        return None;
    }
    let (nv, ni) = (be32(d, 8) as usize, be32(d, 12) as usize);
    let (vo, io) = (be32(d, 28) as usize, be32(d, 32) as usize);
    if d.len() < vo + nv * 32 || d.len() < io + ni * 2 || ni % 3 != 0 {
        return None;
    }
    let vert = |i: usize| -> [f32; 8] {
        let mut v = [0f32; 8];
        for (k, x) in v.iter_mut().enumerate() {
            *x = bef(d, vo + i * 32 + k * 4);
        }
        v
    };
    let mut lo = [f32::MAX; 3];
    let mut hi = [f32::MIN; 3];
    for i in 0..nv {
        let v = vert(i);
        for k in 0..3 {
            lo[k] = lo[k].min(v[k]);
            hi[k] = hi[k].max(v[k]);
        }
    }
    let (c, size) = match fixed {
        Some(span) => ([0.0; 3], span),
        None => (
            [(lo[0] + hi[0]) * 0.5, (lo[1] + hi[1]) * 0.5, (lo[2] + hi[2]) * 0.5],
            (0..3).map(|k| hi[k] - lo[k]).fold(0.0f32, f32::max).max(1e-3),
        ),
    };
    let mut b = Baked { pos: Vec::new(), nrm: Vec::new(), base: Vec::new(), glow: Vec::new() };
    for t in 0..ni {
        let i = u16::from_be_bytes([d[io + t * 2], d[io + t * 2 + 1]]) as usize;
        if i >= nv {
            return None;
        }
        let v = vert(i);
        b.pos.push([(v[0] - c[0]) / size, (v[1] - c[1]) / size, (v[2] - c[2]) / size]);
        b.nrm.push([v[5], v[6], v[7]]);
        b.base.push(sample(atlas, v[3], v[4]));
        b.glow.push(sample(glow, v[3], v[4]));
    }
    Some(b)
}

/// Every model, decoded once.
pub fn models() -> &'static [Baked] {
    static M: OnceLock<Vec<Baked>> = OnceLock::new();
    M.get_or_init(|| {
        let empty = (4usize, 4usize, vec![0u8; 64]);
        let atlas = decode_gxtx(ATLAS).unwrap_or_else(|| empty.clone());
        let glow = decode_gxtx(GLOW).unwrap_or_else(|| empty.clone());
        let patlas = decode_gxtx(PARTY_ATLAS).unwrap_or_else(|| empty.clone());
        let pglow = decode_gxtx(PARTY_GLOW).unwrap_or_else(|| empty.clone());
        let eatlas = decode_gxtx(EM_ATLAS).unwrap_or_else(|| empty.clone());
        let eglow = decode_gxtx(EM_GLOW).unwrap_or(empty);
        MESH_FILES
            .iter()
            .chain(EM_FILES.iter())
            .enumerate()
            .map(|(i, d)| {
                let b = if i >= EM_FIRST {
                    decode_mesh_in(d, &eatlas, &eglow, Some(PARTY_SPAN))
                } else if i >= PARTY_FIRST {
                    decode_mesh_in(d, &patlas, &pglow, Some(PARTY_SPAN))
                } else {
                    decode_mesh(d, &atlas, &glow)
                };
                b.unwrap_or(Baked { pos: Vec::new(), nrm: Vec::new(), base: Vec::new(), glow: Vec::new() })
            })
            .collect()
    })
}

/// Lit colour of model vertex `i` turned by (yaw, pitch): base x (ambient + diffuse) + glow x `glow`.
fn shade(m: &Baked, i: usize, rot: &dyn Fn([f32; 3]) -> [f32; 3], glow: f32) -> [f32; 3] {
    const L: [f32; 3] = [0.35, 0.6, 0.72];
    let n = rot(m.nrm[i]);
    let d = (n[0] * L[0] + n[1] * L[1] + n[2] * L[2]).max(0.0);
    let k = 0.42 + 0.7 * d;
    let (b, g) = (m.base[i], m.glow[i]);
    [(b[0] * k + g[0] * glow).min(1.0), (b[1] * k + g[1] * glow).min(1.0), (b[2] * k + g[2] * glow).min(1.0)]
}

fn rotator(yaw: f32, pitch: f32) -> impl Fn([f32; 3]) -> [f32; 3] {
    let (sy, cy) = yaw.sin_cos();
    let (sp, cp) = pitch.sin_cos();
    move |p: [f32; 3]| {
        let (x, z) = (p[0] * cy + p[2] * sy, -p[0] * sy + p[2] * cy);
        let (y, z) = (p[1] * cp - z * sp, p[1] * sp + z * cp);
        [x, y, z]
    }
}

// ---- the world list (presentation, filled by the UI host each present)

/// One queued world draw.
#[derive(Clone, Copy, Debug)]
pub enum Inst {
    /// model id, centre, yaw, diameter (world units), alpha 0..1, material (melee_gx::fx::MAT_*), its parameters
    /// (glow, charge, Heat state, extra) and colour
    /// `roll`: a turn in the model's own plane before the yaw (a shot laid along its velocity); 0 for a drive
    Model { model: u16, at: [f32; 3], yaw: f32, roll: f32, scale: f32, alpha: f32, mat: u8, p: [f32; 4], rgba: u32 },
    /// an additive effect shape: kind, centre, three numbers, colour RGBA
    Fx { kind: u8, at: [f32; 3], a: f32, b: f32, c: f32, rgba: u32 },
}

pub const FX_RING: u8 = 1;
pub const FX_DISC: u8 = 2;
pub const FX_SPIKES: u8 = 3;
pub const FX_BOLT: u8 = 4;
pub const FX_BEAM: u8 = 5;
pub const FX_LINE: u8 = 6;

/// Per-present cap (budget: 8 orbiters + 2, a drop, a handful of effects).
pub const MAX_INST: usize = 320;

static BUILD: Mutex<Vec<Inst>> = Mutex::new(Vec::new());
static SHOW: Mutex<Vec<Inst>> = Mutex::new(Vec::new());

/// A present begins: nothing queued yet.
pub fn begin() {
    if let Ok(mut b) = BUILD.lock() {
        b.clear();
    }
}

/// Queue one draw (false: the present's cap is reached).
pub fn push(i: Inst) -> bool {
    let Ok(mut b) = BUILD.lock() else { return false };
    if b.len() >= MAX_INST {
        return false;
    }
    b.push(i);
    true
}

/// The present ended: its list is what the world draws until the next one.
pub fn commit() {
    let (Ok(mut b), Ok(mut s)) = (BUILD.lock(), SHOW.lock()) else { return };
    std::mem::swap(&mut *b, &mut *s);
    b.clear();
    if !s.is_empty() {
        // installed on the first present that queues anything: with no Envoy UI the fighter pass is untouched
        unsafe { melee_fighter::tu::ftdrawcommon::WORLD_DRAW = Some(record_camera) };
    }
}

/// Install the fight-camera recorder (the shader effect quads, melee_gx::vfx, are placed with the same camera as
/// the drives; a present that queues only quads still needs it).
pub fn want_camera() {
    unsafe { melee_fighter::tu::ftdrawcommon::WORLD_DRAW = Some(record_camera) };
}

/// Draws presented so far (tests, logs).
pub fn shown() -> usize {
    SHOW.lock().map_or(0, |s| s.len())
}

/// A coloured world triangle vertex (the fire shapes).
pub type Tri = ([f32; 3], [u8; 4]);

fn rgba_of(c: u32, k: f32) -> [u8; 4] {
    let a = ((c & 0xFF) as f32 * k.clamp(0.0, 1.0)) as u8;
    [(c >> 24) as u8, (c >> 16) as u8, (c >> 8) as u8, a]
}

fn quad(out: &mut Vec<Tri>, a: [f32; 3], b: [f32; 3], c: [f32; 3], d: [f32; 3], ca: [u8; 4], cb: [u8; 4]) {
    out.extend_from_slice(&[(a, ca), (b, ca), (c, cb), (a, ca), (c, cb), (d, cb)]);
}

/// The effect shapes, in the stage plane (facing the camera), at `at`'s depth.
fn fx_tris(kind: u8, at: [f32; 3], a: f32, b: f32, c: f32, rgba: u32, out: &mut Vec<Tri>) {
    let col = rgba_of(rgba, 1.0);
    let clear = rgba_of(rgba, 0.0);
    let p = |x: f32, y: f32| [at[0] + x, at[1] + y, at[2]];
    match kind {
        FX_RING => {
            let (r0, r1) = ((a - b * 0.5).max(0.0), a + b * 0.5);
            for s in 0..32 {
                let (t0, t1) = (s as f32 / 32.0 * std::f32::consts::TAU, (s + 1) as f32 / 32.0 * std::f32::consts::TAU);
                let (s0, c0, s1, c1) = (t0.sin(), t0.cos(), t1.sin(), t1.cos());
                quad(out, p(c0 * r0, s0 * r0), p(c1 * r0, s1 * r0), p(c1 * r1, s1 * r1), p(c0 * r1, s0 * r1), col, col);
            }
        }
        FX_DISC => {
            for s in 0..24 {
                let (t0, t1) = (s as f32 / 24.0 * std::f32::consts::TAU, (s + 1) as f32 / 24.0 * std::f32::consts::TAU);
                out.extend_from_slice(&[(p(0.0, 0.0), col), (p(t0.cos() * a, t0.sin() * a), clear), (p(t1.cos() * a, t1.sin() * a), clear)]);
            }
        }
        FX_SPIKES => {
            let n = 8;
            for s in 0..n {
                let t = c + s as f32 / n as f32 * std::f32::consts::TAU;
                let w = 0.22;
                let (ta, tb) = (t - w, t + w);
                out.extend_from_slice(&[
                    (p(ta.cos() * a, ta.sin() * a), col),
                    (p(tb.cos() * a, tb.sin() * a), col),
                    (p(t.cos() * b, t.sin() * b), clear),
                ]);
            }
        }
        FX_BOLT | FX_LINE => {
            // from `at` to (a, b), width c; a bolt zigzags
            let (dx, dy) = (a - at[0], b - at[1]);
            let len = (dx * dx + dy * dy).sqrt().max(1e-3);
            let (nx, ny) = (-dy / len * c * 0.5, dx / len * c * 0.5);
            let segs = if kind == FX_BOLT { 7 } else { 1 };
            let mut prev = [at[0], at[1]];
            for s in 1..=segs {
                let t = s as f32 / segs as f32;
                let j = if kind == FX_BOLT && s < segs { (if s % 2 == 0 { 1.0 } else { -1.0 }) * len * 0.06 } else { 0.0 };
                let cur = [at[0] + dx * t + -dy / len * j, at[1] + dy * t + dx / len * j];
                let q = |x: f32, y: f32| [x, y, at[2]];
                quad(out, q(prev[0] + nx, prev[1] + ny), q(cur[0] + nx, cur[1] + ny), q(cur[0] - nx, cur[1] - ny), q(prev[0] - nx, prev[1] - ny), col, col);
                prev = cur;
            }
        }
        FX_BEAM => {
            // a column of height a, width b, fading upward
            let w = b * 0.5;
            quad(out, p(-w, 0.0), p(w, 0.0), p(w, a), p(-w, a), col, clear);
        }
        _ => {}
    }
}

/// The fighter whose draw pass draws the list (`draw`): any drawn fighter can be it, so the drives stay drawn
/// while slot 0's fighter is not (KO'd, between stocks) (V1 drew in slot 0's pass only).
static mut DRAWER: usize = 0;
/// Fighters seen in pass 0 since the drawer last drew: seeing one twice means a whole render went by without it.
static mut SEEN: [usize; 8] = [0; 8];
static mut SEEN_N: usize = 0;

/// Whether this pass-0 call is the one that draws the list this render: the drawer's own, or (when the drawer was
/// not drawn for a whole render) the first fighter seen twice, which becomes the drawer.
unsafe fn is_drawer(g: usize) -> bool {
    if g == DRAWER {
        SEEN_N = 0;
        return true;
    }
    if SEEN[..SEEN_N].contains(&g) || SEEN_N >= SEEN.len() {
        DRAWER = g;
        SEEN_N = 0;
        return true;
    }
    SEEN[SEEN_N] = g;
    SEEN_N += 1;
    false
}

/// The camera the fighter pass last drew with (view rows, GX projection, viewport): written by [`record_camera`].
static CAM: Mutex<Option<Camera>> = Mutex::new(None);

/// The fight camera (melee_gx::fx::Camera's fields): view matrix rows, `GXGetProjectionv`, `GXGetViewportv`.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Camera {
    pub view: [[f32; 4]; 3],
    pub proj: [f32; 7],
    pub vp: [f32; 6],
}

/// The fighter draw pass hook (`ftdrawcommon::WORLD_DRAW`): pass 0 of one fighter per render (`is_drawer`) copies the
/// current camera into [`CAM`]. No GX commands, no allocation: the presenter draws the list ([`world_frame`]).
pub unsafe fn record_camera(g: *mut melee_types::HSD_GObj, pass: i32) {
    if pass != 0 || g.is_null() || (*g).user_data.is_null() {
        return;
    }
    if !is_drawer(g as usize) {
        return;
    }
    let cobj = melee_runtime::tu::cobj::HSD_CObjGetCurrent();
    if cobj.is_null() {
        return;
    }
    let mut proj = [0f32; 7];
    let mut vp = [0f32; 6];
    melee_runtime::tu::fog::ext::GXGetProjectionv(proj.as_mut_ptr());
    melee_runtime::tu::fog::ext::GXGetViewportv(vp.as_mut_ptr());
    let view = (*cobj).view_mtx;
    if let Ok(mut c) = CAM.lock() {
        *c = Some(Camera { view, proj, vp });
    }
}

/// The last recorded fight camera.
pub fn camera() -> Option<Camera> {
    CAM.lock().ok().and_then(|c| *c)
}

/// The shown list as the effects layer's inputs: each model draw (`f(model, at, yaw, roll, scale, alpha, mat, p, rgba)`)
/// and the fire shapes as additive triangles in `tris`. Presenter side only.
pub fn world_frame(mut f: impl FnMut(u16, [f32; 3], f32, f32, f32, f32, u8, [f32; 4], u32), tris: &mut Vec<Tri>) {
    tris.clear();
    let Ok(list) = SHOW.lock() else { return };
    for i in list.iter() {
        match *i {
            Inst::Model { model, at, yaw, roll, scale, alpha, mat, p, rgba } => f(model, at, yaw, roll, scale, alpha, mat, p, rgba),
            Inst::Fx { kind, at, a, b, c, rgba } => fx_tris(kind, at, a, b, c, rgba, tris),
        }
    }
}

// ---- sprites for the 2D cards (CPU raster)

/// The C comparisons (semantics lint M1: no IEEE min / max / clamp).
fn fmin(a: f32, b: f32) -> f32 {
    if a < b { a } else { b }
}
fn fmax(a: f32, b: f32) -> f32 {
    if a > b { a } else { b }
}
fn clamp01(v: f32) -> f32 {
    if v < 0.0 { 0.0 } else if v > 1.0 { 1.0 } else { v }
}

pub const SPRITE: usize = 64;
pub const SPRITE_FRAMES: usize = 12;

/// `model` turning: SPRITE_FRAMES cells of SPRITE x SPRITE side by side (RGBA, transparent background).
pub fn sprite_sheet(model: usize) -> Option<(usize, usize, Vec<u8>)> {
    let m = models().get(model)?;
    if m.pos.is_empty() {
        return None;
    }
    let (w, h) = (SPRITE * SPRITE_FRAMES, SPRITE);
    let mut px = vec![0u8; w * h * 4];
    let mut zb = vec![f32::MIN; w * h];
    for fr in 0..SPRITE_FRAMES {
        let rot = rotator(fr as f32 / SPRITE_FRAMES as f32 * std::f32::consts::TAU, 0.35);
        let ox = (fr * SPRITE) as f32;
        let s = SPRITE as f32 * 0.86;
        let half = SPRITE as f32 * 0.5;
        for t in (0..m.pos.len()).step_by(3) {
            let v: Vec<[f32; 3]> = (0..3).map(|k| rot(m.pos[t + k])).collect();
            let sc: Vec<[f32; 3]> = v.iter().map(|p| [ox + half + p[0] * s, half - p[1] * s, p[2]]).collect();
            let col: Vec<[f32; 3]> = (0..3).map(|k| shade(m, t + k, &rot, 0.8)).collect();
            let (x0, x1) = (sc.iter().map(|p| p[0]).fold(f32::MAX, fmin).floor(), sc.iter().map(|p| p[0]).fold(f32::MIN, fmax).ceil());
            let (y0, y1) = (sc.iter().map(|p| p[1]).fold(f32::MAX, fmin).floor(), sc.iter().map(|p| p[1]).fold(f32::MIN, fmax).ceil());
            let (x0, x1) = (fmax(x0, ox) as usize, fmin(x1, ox + SPRITE as f32 - 1.0) as usize);
            let (y0, y1) = (fmax(y0, 0.0) as usize, fmin(y1, h as f32 - 1.0) as usize);
            let area = (sc[1][0] - sc[0][0]) * (sc[2][1] - sc[0][1]) - (sc[2][0] - sc[0][0]) * (sc[1][1] - sc[0][1]);
            if area.abs() < 1e-6 {
                continue;
            }
            for y in y0..=y1 {
                for x in x0..=x1 {
                    let (fx, fy) = (x as f32 + 0.5, y as f32 + 0.5);
                    let e = |a: [f32; 3], b: [f32; 3]| (b[0] - a[0]) * (fy - a[1]) - (b[1] - a[1]) * (fx - a[0]);
                    let (w0, w1, w2) = (e(sc[1], sc[2]) / area, e(sc[2], sc[0]) / area, e(sc[0], sc[1]) / area);
                    if w0 < 0.0 || w1 < 0.0 || w2 < 0.0 {
                        continue;
                    }
                    let z = w0 * sc[0][2] + w1 * sc[1][2] + w2 * sc[2][2];
                    let o = y * w + x;
                    if z <= zb[o] {
                        continue;
                    }
                    zb[o] = z;
                    for k in 0..3 {
                        px[o * 4 + k] = (clamp01(w0 * col[0][k] + w1 * col[1][k] + w2 * col[2][k]) * 255.0) as u8;
                    }
                    px[o * 4 + 3] = 255;
                }
            }
        }
    }
    Some((w, h, px))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn models_decode_and_sprites_cover() {
        let ms = models();
        assert_eq!(ms.len(), MODEL_COUNT);
        for (i, m) in ms.iter().enumerate() {
            assert!(m.pos.len() >= 48 && m.pos.len() % 3 == 0, "model {i}: {} vertices", m.pos.len());
            // legacy: unit diameter; Party: the shared frame (the halo rides over the form, to 1.86 / 4.4 * 2.2)
            let lim = if i >= PARTY_FIRST { 0.95 } else { 0.51 };
            assert!(m.pos.iter().all(|p| p.iter().all(|v| v.abs() <= lim)), "model {i} out of bounds");
        }
        // the include list and the generator's manifest agree (packaging count: 65 Party models)
        assert_eq!(PARTY_KEYS.lines().count(), PARTY_COUNT);
        assert_eq!(MESH_FILES.len() + EM_FILES.len(), MODEL_COUNT);
        let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/../../pc/scripts/examples/envoy_drives/models/");
        for (k, key) in PARTY_KEYS.lines().enumerate() {
            let disk = std::fs::read(format!("{dir}drive_{key}.gxmesh")).expect(key);
            assert!(disk == MESH_FILES[PARTY_FIRST + k], "include list out of order at {key}");
        }
        assert_eq!(PARTY_KEYS.lines().nth(M_ASCENDED - PARTY_FIRST), Some("ascended"));
        assert!(is_drive_body(PARTY_FIRST + 3) && !is_drive_body(M_RING_EPIC) && is_unique(PARTY_END - 1) && !is_unique(EM_FIRST) && is_drive_body(EM_FIRST));
        // the Envoy model set: the generated include list follows the manifest, every model decodes in the Party
        // frame, and a sprite of one covers its cell
        assert_eq!(EM_KEYS.lines().count(), EM_COUNT);
        let edir = concat!(env!("CARGO_MANIFEST_DIR"), "/../../pc/scripts/examples/envoy_models/models/");
        for (k, key) in EM_KEYS.lines().enumerate() {
            let disk = std::fs::read(format!("{edir}em_{key}.gxmesh")).expect(key);
            assert!(disk == EM_FILES[k], "envoy_models include list out of order at {key}");
            assert!(!ms[EM_FIRST + k].pos.is_empty(), "em_{key} did not decode");
        }
        assert_eq!(em_model("spark_ring"), Some(EM_FIRST));
        assert_eq!(em_model("no_such_model"), None);
        // Spare Heart is pink-red (its item colour), the shop frame teal: the new atlas rows land where the generator put them
        let eavg = |m: &Baked| m.base.iter().fold([0.0f32; 3], |a, c| [a[0] + c[0], a[1] + c[1], a[2] + c[2]]);
        let h = eavg(&ms[em_model("heart_full").unwrap()]);
        let f = eavg(&ms[em_model("frame_shop").unwrap()]);
        assert!(h[0] > h[1] && h[0] > h[2], "heart {h:?}");
        assert!(f[1] > f[0] && f[2] > f[0], "shop frame {f:?}");
        let (ew, eh, epx) = sprite_sheet(em_model("node_boss").unwrap()).unwrap();
        assert!(epx.chunks(4).filter(|p| p[3] != 0).count() > ew * eh / 20, "boss node sprite is empty");
        // the ember is orange (the Fire row), not the legacy red
        let e = &ms[PARTY_FIRST + 3];
        let a = e.base.iter().fold([0.0f32; 3], |a, c| [a[0] + c[0], a[1] + c[1], a[2] + c[2]]);
        assert!(a[0] > a[1] && a[1] > a[2], "ember {a:?}");
        // the red body is red, the blue body blue (the atlas rows land where make_drives.py put them)
        let avg = |m: &Baked| m.base.iter().fold([0.0f32; 3], |a, c| [a[0] + c[0], a[1] + c[1], a[2] + c[2]]);
        let (r, b) = (avg(&ms[0]), avg(&ms[2]));
        assert!(r[0] > r[2] && b[2] > b[0], "red {r:?} blue {b:?}");
        let (w, h, px) = sprite_sheet(0).unwrap();
        assert_eq!((w, h), (SPRITE * SPRITE_FRAMES, SPRITE));
        let cover = px.chunks(4).filter(|p| p[3] != 0).count();
        assert!(cover > w * h / 12, "coverage {cover}");
    }

    #[test]
    fn list_commits() {
        begin();
        assert!(push(Inst::Fx { kind: FX_RING, at: [0.0; 3], a: 5.0, b: 1.0, c: 0.0, rgba: 0xFFFF_FFFF }));
        commit();
        assert_eq!(shown(), 1);
        begin();
        commit();
        assert_eq!(shown(), 0);
    }
}
